pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let seed = 11572758976476374866;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        // Penalize bins that cannot fit the next item immediately
        if post_residual < next_item_size {
            score -= (next_item_size - post_residual) as f64 * seed as f64;
        }

        // Reward bins with a high potential for fitting future items
        let lookahead_potential = mean_residual + next_item_size as f64 / 2.0;
        if post_residual >= lookahead_potential {
            score += (post_residual - lookahead_potential) as f64 * seed as f64;
        }
    }

    // Penalize bins that leave too much unused space
    if bin_capacity - post_residual > mean_residual {
        let excess_space = (bin_capacity - post_residual) as f64 - mean_residual;
        score -= excess_space * seed as f64;
    }

    // Reward bins that are almost full but can still fit the current item
    if bin_residual < 20 && bin_residual >= item_size {
        score += (20 - bin_residual) as f64 * seed as f64;
    }

    score
}

